188	/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
189	fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
190	    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
191	    for pkg in graph.packages() {
192	        let tmpl = pkg
193	            .tag_template
194	            .clone()
195	            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
196	        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
197	        *has_default |= pkg.tag_template.is_none();
198	        ids.push(pkg.id.clone());
199	    }
200	    match by_template
201	        .into_iter()
202	        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
203	    {
204	        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
205	        None => Ok(()),
206	    }
207	}
