270	            if pkg.tag_template.is_some() || pkg.id.ecosystem().is_some() {
271	                continue;
272	            }
273	            let (Some(manifest), Ok(grammar)) = (pkg.canonical_manifests().next(), pkg.version_grammar()) else {
274	                continue;
275	            };
276	            let tmpl = TagTemplate::default_for(&pkg.id);
277	            let Ok(candidates) = candidates_cached(&all_tags, &tmpl, &mut glob_cache) else {
278	                continue;
279	            };
280	            let Ok(tags) = rank_tags(&tmpl, grammar, candidates.iter().copied()) else {
281	                continue;
282	            };
283	            if let Some(tag) = tags.ordered.first() {
284	                wanted.push((tag_commits.rev_of(git, tag.name.as_str()), manifest.path.clone()));
285	            }
286	            ranked.insert(pkg.id.clone(), tags);
287	        }
288	        rosters.prefetch(git, &wanted);
289	
290	        for pkg in graph.packages() {
291	            // `TagTemplate::default_for` is the source of truth and matches `release.rs`; `parse` adds git-ref legality checks that `default_for` skips.
292	            let tmpl = pkg
293	                .tag_template
294	                .clone()
295	                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
296	            let grammar = pkg.version_grammar()?;
297	            let mut chosen = if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
298	                // A bare name is the only evidence the default template has, so a tag is the package's only if its
299	                // commit did not hold the name in another ecosystem.
300	                let tags = match ranked.remove(&pkg.id) {
301	                    Some(tags) => tags,
302	                    None => rank_tags(
303	                        &tmpl,
304	                        grammar,
305	                        candidates_cached(&all_tags, &tmpl, &mut glob_cache)?.iter().copied(),
306	                    )
307	                    .map_err(GraphError::from)?,
308	                };
309	                record_skipped(tags.skipped, &mut diagnostics);
310	                let mut chosen = None;
311	                for tag in tags.ordered {
312	                    // History that cannot be read is no evidence of another owner.
313	                    let held = crate::history::may_have_held_name_at(
314	                        git,
315	                        &tag_commits.rev_of(git, tag.name.as_str()),
316	                        pkg.id.name(),
317	                        pkg,
318	                        identity,
319	                        &mut rosters,
320	                    )
321	                    .unwrap_or(true);
322	                    if held {
323	                        chosen = Some(tag);
324	                        break;
325	                    }
326	                    diagnostics.push(foreign_tag_diagnostic(&pkg.id, tag.name.as_str()));
327	                    foreign
328	                        .entry(pkg.id.clone())
329	                        .or_default()
330	                        .insert(tag.name.as_str().to_string());
331	                }
332	                chosen
333	            } else {
334	                take_chosen(
335	                    select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
336	                    &mut diagnostics,
337	                )
338	            };
339	            if chosen.is_none() {
340	                let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
341	                if let Some(previous) = crate::config::resolve::resolve_package_config(&native_names, cfg)
342	                    .map(|package_config| package_config.previous_tag_templates.as_slice())
343	                {
