346	                            select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
347	                            &mut diagnostics,
348	                        );
349	                        if chosen.is_some() {
350	                            break;
351	                        }
352	                    }
353	                }
354	            }
355	            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
356	                // A promoted package keeps the `{name}@` tags it made while its name was unique.
357	                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
358	                let same: Vec<&callisto_model::Package> = graph
359	                    .packages()
360	                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
361	                    .collect();
362	                let mut owned = Vec::new();
363	                for tag in matching_tags(&all_tags, &unqualified)? {
364	                    let rev = tag_commits.rev_of(git, tag);
365	                    if crate::history::sole_owner_at(git, &rev, pkg.id.name(), &same, identity, &mut rosters)?
366	                        .is_some_and(|owner| owner.id == pkg.id)
367	                    {
368	                        owned.push(tag);
369	                    }
370	                }
371	                chosen = take_chosen(
372	                    select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
373	                    &mut diagnostics,
