375	            }
376	            if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
377	                // A demoted package keeps the qualified tags it made while its name was shared.
378	                if let Some(manifest) = pkg.canonical_manifests().next() {
379	                    let qualified = TagTemplate::default_for(&PackageId::Prefixed {
380	                        ecosystem: manifest.ecosystem(),
381	                        name: pkg.id.name().to_string(),
