384	                        select_last_tag(&qualified, grammar, all_tags.0.iter().copied()).map_err(GraphError::from)?,
385	                        &mut diagnostics,
386	                    );
387	                    chosen = newest(chosen, qualified_last);
388	                }
389	            }
390	            last.insert(pkg.id.clone(), chosen);
391	            templates.insert(pkg.id.clone(), tmpl);
392	        }
