//! The commands that read a whole workspace start the same git processes however many packages it has.

use std::process::Command;

use callisto_fixtures::perf::{PackageKind, ScaledWorkspace};

/// Runs `callisto` over a workspace of `packages` and returns how many git processes it started.
fn git_processes(kind: PackageKind, packages: usize, args: &[&str]) -> usize {
    let repository = tempfile::tempdir().unwrap();
    ScaledWorkspace {
        kind,
        packages,
        extra_commits: packages,
    }
    .build(repository.path());
    let trace_dir = tempfile::tempdir().unwrap();
    let trace = trace_dir.path().join("trace.json");
    let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
        .arg("--cwd")
        .arg(repository.path())
        .args(args)
        .env("GIT_TRACE2_EVENT", &trace)
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "callisto {args:?}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::fs::read_to_string(&trace)
        .unwrap()
        .lines()
        .filter(|line| line.contains("\"event\":\"start\""))
        .count()
}

fn assert_independent_of_package_count(args: &[&str]) {
    let few = git_processes(PackageKind::Cargo, 6, args);
    let many = git_processes(PackageKind::Cargo, 30, args);
    assert_eq!(

fn measure(root: &Path, args: &[&str], trace: &Path) -> Measured {
    drop(std::fs::remove_file(trace));
    let started = Instant::now();
    let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
        .arg("--cwd")
        .arg(root)
        .args(args)
        .env("GIT_TRACE2_EVENT", trace)
        .output()
        .unwrap();
    let wall = started.elapsed();
    let trace_text = std::fs::read_to_string(trace).unwrap_or_default();
    let mut shapes = std::collections::BTreeMap::new();
    for shape in trace_text.lines().filter_map(shape_of) {
        *shapes.entry(shape).or_insert(0) += 1;
    }
    let git_time = Duration::from_secs_f64(trace_text.lines().filter_map(exit_seconds).sum());
    let mut shape_by_session = std::collections::BTreeMap::new();
    let mut shape_seconds = std::collections::BTreeMap::new();
    for line in trace_text.lines() {
        let Ok(event) = serde_json::from_str::<serde_json::Value>(line) else {
            continue;
        };
        let session = event
            .get("sid")
            .and_then(|sid| sid.as_str())
            .unwrap_or_default()
            .to_owned();
        if let Some(shape) = shape_of(line) {
            shape_by_session.insert(session, shape);
        } else if let (Some(seconds), Some(shape)) = (exit_seconds(line), shape_by_session.get(&session)) {
            *shape_seconds.entry(shape.clone()).or_insert(0.0) += seconds;
        }
    }
